def check_target_evidence_reference(ws):
    try:
        with sqlite3.connect(_db(ws)) as con:
            con.row_factory = sqlite3.Row
            row = con.execute(
                "SELECT asset_evidence_reference FROM transformer_assets WHERE asset_id = ?",
                (TARGET,),
            ).fetchone()
            logs = con.execute(
                "SELECT approved_by FROM asset_evidence_update_log WHERE asset_id = ? AND asset_evidence_reference = ?",
                (TARGET, EXPECTED_REFERENCE),
            ).fetchall()
        if row is None:
            return {"score": 0, "detail": "Target asset not found."}
        if row["asset_evidence_reference"] != EXPECTED_REFERENCE:
            return {"score": 0, "detail": "Target evidence reference is not the issued panel decision identifier."}
        if len(logs) != 1 or logs[0]["approved_by"] != "Sarah Chen":
            return {"score": 0, "detail": "The target update is missing or has the wrong approver."}
        return {"score": 1, "detail": "Target evidence reference and approver are correct."}
