                "SELECT asset_id, previous_evidence_reference, asset_evidence_reference, expected_updated_at "
                "FROM asset_evidence_update_log ORDER BY update_id"
            ).fetchall()
        if len(rows) != 1:
            return {"score": 0, "detail": f"Expected exactly one evidence-update audit row overall, found {len(rows)}."}
