"""Check optional Z33 case-count/list claims against the source workbook."""

import re
from openpyxl import load_workbook

def check_z33_claim_consistency(workspace):
    answer = (workspace / "answer.md").read_text(encoding="utf-8") if (workspace / "answer.md").exists() else ""
    source = workspace / "02_预分组分析/澄湖人民医院2025年2月病案首页分组质控清单.xlsx"
    if not source.exists():
        return {"score": 0, "detail": "质控清单缺失"}
    ws = load_workbook(source, data_only=True, read_only=True)["异常病案清单"]
    closed = set()
    for row in ws.iter_rows(min_row=7, values_only=True):
        case, desc, orig, conclusion, completion, release = row[2], row[8], row[10], row[22], row[25], row[26]
        if ((str(orig or "").startswith("Z33") or "Z33" in str(desc or ""))
                and completion and conclusion in {"同意修改", "维持原值", "补充证据后通过"}
                and release == "已放行"):
            closed.add(str(case))
    if closed != {"250210455", "250210972"}:
        return {"score": 0, "detail": "源清单闭环集合异常"}
    # Only police claims explicitly tied to the Z33 case evidence, leaving omission acceptable.
    for line in answer.splitlines():
        if "Z33" not in line:
            continue
        counts = []
        counts += re.findall(r"(?<!\d)(\d+)\s*例[^，。；;]{0,20}(?:Z33|妊娠状态)", line)
        counts += re.findall(r"(?:Z33|妊娠状态)[^，。；;]{0,20}?(\d+)\s*例", line)
